import { computeDailySkinScore, computeSkinAgeIndex, computeSubScores } from "./scoring.ts";
import {
  CHALLENGE_LENGTH,
  type AppState,
  type DayRecord,
  type Experiment,
  type RawMetrics,
  type Survey,
} from "./types.ts";

/**
 * Deterministic demo data for the "Live Demo" in the IR deck and for anyone
 * exploring the app without 15 real days of selfies.
 *
 * Raw metrics are generated by *inverting* the scoring ramps, so every demo
 * day's sub-scores and Daily Skin Score come out of the same
 * `computeSubScores` / `computeDailySkinScore` path real captures use — the
 * demo never carries a number the engine could not have produced.
 */

export const DEMO_SURVEY: Survey = {
  concerns: ["trouble", "spots"],
  skinType: "combination",
  condition: "normal",
  outdoor: "light",
  products: ["클렌징 폼", "수분 크림"],
  sleep: "normal",
  age: 16,
};

export const DEMO_EXPERIMENT: Experiment = {
  id: "demo-exp-1",
  kind: "add-product",
  title: "논코메도제닉 선크림 추가",
  startDay: 4,
  target: "trouble",
  createdAt: "2026-09-01T00:00:00.000Z",
};

/** Per-index target scores, Day 1 → Day 15 (deck slide 7/8 shape). */
const TRAJECTORY: Array<[trouble: number, spot: number, naso: number, forehead: number]> = [
  [52, 60, 66, 58], // D1 baseline
  [54, 61, 66, 59],
  [56, 61, 65, 60],
  [53, 60, 64, 60], // D4 experiment starts — short adaptation dip
  [50, 59, 63, 59],
  [52, 60, 63, 61],
  [58, 61, 64, 62], // D7 turns
  [62, 62, 65, 64],
  [65, 63, 65, 65],
  [67, 64, 66, 67],
  [70, 65, 66, 68],
  [73, 66, 67, 70],
  [75, 67, 67, 71],
  [77, 68, 68, 72],
  [79, 69, 68, 74], // D15
];

/** Inverse of scoring.ts `invertedScore`: the raw reading that yields `score`. */
function rawFor(score: number, best: number, worst: number) {
  return best + (1 - score / 100) * (worst - best);
}

function metricsForDay(index: number): RawMetrics {
  const [trouble, spot, naso, forehead] = TRAJECTORY[index];
  // One deliberately worse capture (Day 6: over-exposed) so the consistency
  // warning has something real to point at.
  const badCapture = index === 5;
  const troubleAreaRatio = rawFor(trouble, 0.002, 0.06);
  const spotDensity = rawFor(spot, 0.004, 0.09);
  return {
    troubleAreaRatio,
    troubleCount: Math.round(troubleAreaRatio * 260),
    spotDensity,
    spotCount: Math.round(spotDensity * 210),
    spotBalance: { left: 0.54, right: 0.46 },
    nasolabialProminence: rawFor(naso, 0.02, 0.18),
    nasolabialSymmetry: 0.9,
    foreheadLineProminence: rawFor(forehead, 0.02, 0.16),
    foreheadLineCount: Math.max(0, Math.round((100 - forehead) / 18)),
    sharpness: badCapture ? 190 : 330 + (index % 3) * 12,
    exposure: badCapture ? 178 : 132 + (index % 4) * 2,
  };
}

const MISSED_ROUTINE = new Set([5, 9]);
const TOUCHED_FACE = new Set([1, 2, 8]);
const SKIPPED_EXPERIMENT = new Set([9]);

function isoDaysAgo(from: Date, daysAgo: number) {
  const d = new Date(from);
  d.setDate(d.getDate() - daysAgo);
  return d.toISOString().slice(0, 10);
}

/**
 * Builds `days` consecutive records ending today. Photos are not seeded —
 * `StoredPhoto` falls back to the design-board portraits, which is the same
 * thing the Stitch comps show.
 */
export function buildDemoRecords(days: number, today = new Date(), survey = DEMO_SURVEY): DayRecord[] {
  const n = Math.max(1, Math.min(CHALLENGE_LENGTH, days));
  const out: DayRecord[] = [];
  for (let i = 0; i < n; i++) {
    const day = i + 1;
    const metrics = metricsForDay(i);
    const subScores = computeSubScores(metrics);
    const dailySkinScore = computeDailySkinScore(subScores);
    out.push({
      day,
      date: isoDaysAgo(today, n - 1 - i),
      metrics,
      subScores,
      dailySkinScore,
      skinAgeIndex: computeSkinAgeIndex(dailySkinScore, survey),
      photoKeys: {},
      sunExposure: day === 6 || day === 11,
      completedActions: MISSED_ROUTINE.has(day) ? [] : ["keep-routine", "face-yoga"],
      routineDone: !MISSED_ROUTINE.has(day),
      noTouch: !TOUCHED_FACE.has(day),
      experimentApplied:
        day >= DEMO_EXPERIMENT.startDay ? !SKIPPED_EXPERIMENT.has(day) : undefined,
    });
  }
  return out;
}

export function buildDemoState(days: number, base: AppState, today = new Date()): AppState {
  const records = buildDemoRecords(days, today);
  return {
    ...base,
    survey: DEMO_SURVEY,
    onboardedAt: new Date(`${records[0].date}T09:00:00`).toISOString(),
    records,
    challengeJoined: true,
    nickname: base.nickname === "Amy" ? "하은" : base.nickname,
    experiment: DEMO_EXPERIMENT,
    inviteCode: "GLOW-7K2M",
  };
}
